<template data-product-edit-modal-template>
    <div class="product-crud-surface fixed inset-0 z-[100] flex items-center justify-center bg-[#101633]/60 p-3 backdrop-blur-sm sm:p-6" role="dialog" aria-modal="true" aria-labelledby="product-edit-modal-title">
        <button type="button" data-close-product-modal class="absolute inset-0 h-full w-full cursor-default" aria-label="Tutup formulir produk"></button>
        <section class="relative z-10 flex max-h-[calc(100vh-1.5rem)] w-full max-w-4xl flex-col overflow-hidden rounded-[28px] border border-[#e6eaff] bg-white shadow-[0_30px_100px_rgba(15,23,60,0.34)] sm:max-h-[calc(100vh-3rem)]">
            <header class="relative flex shrink-0 items-center justify-between gap-4 border-b border-[#edf0fb] px-5 py-4 sm:px-7 sm:py-5">
                <span class="absolute inset-x-0 top-0 h-1 bg-gradient-to-r from-[#536dfe] via-[#8293ff] to-[#54c8e8]"></span>
                <div class="flex min-w-0 items-center gap-4"><span class="flex h-12 w-12 shrink-0 items-center justify-center rounded-2xl bg-[#eef1ff] text-[#536dfe]"><svg viewBox="0 0 24 24" class="h-6 w-6" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><path d="m14 5 5 5M4 20l4.5-1 11-11a2.1 2.1 0 0 0-3-3l-11 11L4 20Z"/><path d="M4 20h5"/></svg></span><div><p class="text-xs font-bold uppercase tracking-[0.16em] text-[#687eff]">Katalog produk</p><h2 id="product-edit-modal-title" data-product-edit-title class="mt-1 text-lg font-semibold tracking-tight text-[#20284a] sm:text-xl">Edit produk</h2><p class="mt-1 hidden text-sm text-[#7b8299] sm:block">Perbarui foto, identitas, harga, dan status produk.</p></div></div>
                <button type="button" data-close-product-modal class="flex h-10 w-10 shrink-0 items-center justify-center rounded-xl bg-[#f4f6fc] text-xl text-[#68708b] transition hover:rotate-90 hover:bg-[#e9edfa] focus-visible:outline-none focus-visible:ring-4 focus-visible:ring-[#536dfe]/15" aria-label="Tutup">×</button>
            </header>
            <div data-entity-loading class="p-10 text-center text-sm text-[#5e647f]"><span class="inline-flex items-center gap-2"><span class="h-2 w-2 animate-pulse rounded-full bg-[#687EFF]"></span>Memuat informasi produk…</span></div>
            <div data-entity-message class="mx-5 mt-5 hidden rounded-xl border px-4 py-3 text-sm sm:mx-7" role="status" aria-live="polite"></div>
            <form data-product-edit-form class="hidden min-h-0 flex-1 space-y-6 overflow-y-auto p-5 sm:p-7" enctype="multipart/form-data">
                <section class="space-y-4"><div><p class="text-xs font-bold uppercase tracking-[0.12em] text-[#687eff]">01 · Identitas</p><h3 class="mt-1 font-semibold text-[#20284a]">Nama dan pengelompokan</h3></div><div class="grid gap-4 sm:grid-cols-2">
                    <label class="space-y-1.5 text-sm font-semibold sm:col-span-2">Nama produk <span class="text-rose-600">*</span><input name="name" required maxlength="150" class="min-h-11 w-full rounded-xl border border-[#e4e8f4] bg-[#fafbff] px-3.5 text-sm font-normal text-[#20284a] outline-none transition focus:border-[#8697ff] focus:ring-4 focus:ring-[#536dfe]/10"></label>
                    <label class="space-y-1.5 text-sm font-semibold">SKU <span class="text-rose-600">*</span><input name="sku" required maxlength="80" class="min-h-11 w-full rounded-xl border border-[#e4e8f4] bg-[#fafbff] px-3.5 text-sm font-normal uppercase text-[#20284a] outline-none transition focus:border-[#8697ff] focus:ring-4 focus:ring-[#536dfe]/10"></label>
                    <label class="space-y-1.5 text-sm font-semibold">Barcode<input name="barcode" maxlength="100" class="min-h-11 w-full rounded-xl border border-[#e4e8f4] bg-[#fafbff] px-3.5 text-sm font-normal text-[#20284a] outline-none transition focus:border-[#8697ff] focus:ring-4 focus:ring-[#536dfe]/10"></label>
                    <label class="space-y-1.5 text-sm font-semibold sm:col-span-2">Kategori <span class="text-rose-600">*</span><select name="category_id" required class="min-h-11 w-full rounded-xl border border-[#e4e8f4] bg-[#fafbff] px-3.5 text-sm text-[#20284a] outline-none transition focus:border-[#8697ff] focus:ring-4 focus:ring-[#536dfe]/10"></select></label>
                    <label class="space-y-1.5 text-sm font-semibold sm:col-span-2">Deskripsi<textarea name="description" rows="2" class="w-full rounded-xl border border-[#e4e8f4] bg-[#fafbff] px-3.5 py-3 text-sm font-normal text-[#20284a] outline-none transition focus:border-[#8697ff] focus:ring-4 focus:ring-[#536dfe]/10"></textarea></label>
                </div></section>
                <section class="space-y-4 border-t border-[#edf0fb] pt-6"><div><p class="text-xs font-bold uppercase tracking-[0.12em] text-[#687eff]">02 · Foto produk</p><h3 class="mt-1 font-semibold text-[#20284a]">Unggah atau ganti foto</h3></div>
                    <div data-photo-dropzone class="group relative flex min-h-36 cursor-pointer flex-col items-center justify-center overflow-hidden rounded-2xl border-2 border-dashed border-[#cfd8f5] bg-[#fafbff] p-5 text-center transition hover:border-[#8293ff] hover:bg-[#f7f8ff] focus-within:border-[#687eff] focus-within:ring-4 focus-within:ring-[#536dfe]/10">
                        <input data-product-photo name="photo" type="file" accept="image/jpeg,image/png,image/webp" aria-label="Pilih atau seret foto produk" class="absolute inset-0 z-10 h-full w-full cursor-pointer opacity-0">
                        <img data-photo-preview alt="Pratinjau foto produk" class="absolute inset-0 hidden h-full w-full object-contain p-3">
                        <div data-photo-empty class="pointer-events-none flex flex-col items-center"><span class="flex h-12 w-12 items-center justify-center rounded-2xl bg-[#eef1ff] text-[#536dfe]"><svg viewBox="0 0 24 24" class="h-6 w-6" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><path d="m4 7 8-4 8 4v10l-8 4-8-4V7Z"/><path d="m4 7 8 4 8-4M12 11v10"/></svg></span><p class="mt-2 text-sm font-semibold text-[#303858]">Seret foto ke sini atau <span class="text-[#536dfe]">pilih file</span></p><p class="mt-1 text-xs text-[#8a91a9]">JPG, PNG, atau WebP · maksimal 3 MB</p></div>
                        <span data-photo-change class="pointer-events-none absolute bottom-3 z-20 hidden rounded-lg bg-[#20284a]/85 px-3 py-1.5 text-xs font-semibold text-white">Ganti foto</span>
                    </div>
                    <label class="hidden items-center gap-2 text-sm font-medium text-[#737b96]"><input data-remove-product-photo name="remove_photo" type="checkbox" value="1" class="rounded border-[#cbd3e8] text-[#536dfe] focus:ring-[#536dfe]/20">Hapus foto dan gunakan gambar default</label>
                </section>
                <section class="space-y-4 border-t border-[#edf0fb] pt-6"><div><p class="text-xs font-bold uppercase tracking-[0.12em] text-[#687eff]">03 · Harga dan status</p><h3 class="mt-1 font-semibold text-[#20284a]">Pengaturan penjualan</h3></div><div class="grid gap-4 sm:grid-cols-2">
                    <label class="space-y-1.5 text-sm font-semibold">Harga modal (Rp) <span class="text-rose-600">*</span><input name="purchase_price" type="number" min="0" step="1" required class="min-h-11 w-full rounded-xl border border-[#e4e8f4] bg-[#fafbff] px-3.5 text-sm font-normal text-[#20284a] outline-none transition focus:border-[#8697ff] focus:ring-4 focus:ring-[#536dfe]/10"></label>
                    <label class="space-y-1.5 text-sm font-semibold">Harga jual (Rp) <span class="text-rose-600">*</span><input name="selling_price" type="number" min="0" step="1" required class="min-h-11 w-full rounded-xl border border-[#e4e8f4] bg-[#fafbff] px-3.5 text-sm font-normal text-[#20284a] outline-none transition focus:border-[#8697ff] focus:ring-4 focus:ring-[#536dfe]/10"></label>
                    <label class="space-y-1.5 text-sm font-semibold">Satuan<input name="unit" maxlength="30" class="min-h-11 w-full rounded-xl border border-[#e4e8f4] bg-[#fafbff] px-3.5 text-sm font-normal text-[#20284a] outline-none transition focus:border-[#8697ff] focus:ring-4 focus:ring-[#536dfe]/10"></label>
                    <label class="space-y-1.5 text-sm font-semibold">Status<select name="is_active" class="min-h-11 w-full rounded-xl border border-[#e4e8f4] bg-[#fafbff] px-3.5 text-sm text-[#20284a] outline-none transition focus:border-[#8697ff] focus:ring-4 focus:ring-[#536dfe]/10"><option value="1">Aktif</option><option value="0">Nonaktif</option></select></label>
                </div></section>
                <section class="space-y-4 border-t border-[#edf0fb] pt-6"><div><p class="text-xs font-bold uppercase tracking-[0.12em] text-[#687eff]">04 · Stok</p><h3 class="mt-1 font-semibold text-[#20284a]">Tambah stok produk</h3><p class="text-sm text-[#7b8299]">Stok saat ini: <strong data-edit-product-stock class="text-[#20284a]">Memuat…</strong></p></div><div class="grid gap-4 sm:grid-cols-2"><label class="space-y-1.5 text-sm font-semibold">Jumlah stok masuk <span class="text-rose-600">*</span><input data-stock-quantity type="number" min="1" step="1" inputmode="numeric" class="min-h-11 w-full rounded-xl border border-[#e4e8f4] bg-[#fafbff] px-3.5 text-sm font-normal text-[#20284a] outline-none transition focus:border-[#8697ff] focus:ring-4 focus:ring-[#536dfe]/10"></label><label class="space-y-1.5 text-sm font-semibold">Catatan (opsional)<input data-stock-notes maxlength="1000" placeholder="Contoh: restok dari pemasok" class="min-h-11 w-full rounded-xl border border-[#e4e8f4] bg-[#fafbff] px-3.5 text-sm font-normal text-[#20284a] outline-none transition focus:border-[#8697ff] focus:ring-4 focus:ring-[#536dfe]/10"></label></div><div data-stock-message class="hidden rounded-xl border px-4 py-3 text-sm" role="status" aria-live="polite"></div><button type="button" data-adjust-stock class="inline-flex min-h-10 items-center justify-center rounded-xl border border-[#dce3ff] bg-[#f5f7ff] px-4 text-sm font-semibold text-[#536dfe] transition hover:bg-[#eaf0ff]">Tambah stok</button></section>
                <div class="flex flex-col-reverse gap-2 border-t border-[#edf0fb] pt-5 sm:flex-row sm:justify-end"><button type="button" data-close-product-modal class="inline-flex min-h-11 items-center justify-center rounded-xl border border-[#e4e8f4] bg-white px-4 text-sm font-semibold text-[#59617d] transition hover:bg-[#f8f9fd]">Batal</button><button type="submit" class="inline-flex min-h-11 items-center justify-center gap-2 rounded-xl bg-gradient-to-r from-[#536dfe] to-[#687eff] px-5 text-sm font-semibold text-white shadow-[0_8px_18px_rgba(83,109,254,0.2)] transition hover:-translate-y-0.5 hover:from-[#435ce7] hover:to-[#596ff5] disabled:cursor-wait disabled:opacity-60"><svg viewBox="0 0 24 24" class="h-4 w-4" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true"><path d="M5 12h14m-7-7 7 7-7 7"/></svg><span>Simpan perubahan</span></button></div>
            </form>
        </section>
    </div>
</template>
